import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (
    'limit' in message &&
    (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0)
  ) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  let before: {sessionId: string; updatedAt: string | number} | undefined;
  if ('before' in message) {
    const value = message.before;
    if (typeof value !== 'object' || value === null || Array.isArray(value)) {
      return {valid: false, error: 'list_sessions before must be a cursor'};
    }
    const cursor = value as Record<string, unknown>;
    const timestamp = cursor.updatedAt;
    if (
      typeof cursor.sessionId !== 'string' ||
      cursor.sessionId.length < 1 ||
      cursor.sessionId.length > 128 ||
      !isValidCursorTimestamp(timestamp)
    ) {
      return {valid: false, error: 'list_sessions before must have a sessionId and valid updatedAt'};
    }
    before = {sessionId: cursor.sessionId, updatedAt: timestamp};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...('limit' in message ? {limit: message.limit as number} : {}),
      ...(before ? {before} : {}),
    },
  };
}

function isValidCursorTimestamp(value: unknown): value is string | number {
  return (typeof value === 'string' || typeof value === 'number') && Number.isFinite(new Date(value).getTime());
}

import {validateMessage} from './validation.js';

describe('list_sessions validation', () => {
  it('accepts a bare request, strips unknown fields, and rejects malformed paging values', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 0,
        before: {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'},
        userId: 'another-user',
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 0,
        before: {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'},
      },
    });

    for (const limit of [-1, 1.5, 'ten']) {
      expect(validateMessage({type: 'list_sessions', limit})).toEqual({
        valid: false,
        error: expect.stringContaining('limit'),
      });
    }
    for (const before of [
      'not-an-object',
      {sessionId: '', updatedAt: '2026-01-01T00:00:00.000Z'},
      {sessionId: 'a'.repeat(129), updatedAt: '2026-01-01T00:00:00.000Z'},
      {sessionId: 's1', updatedAt: 'not-a-date'},
      {sessionId: 's1', updatedAt: true},
    ]) {
      expect(validateMessage({type: 'list_sessions', before})).toEqual({
        valid: false,
        error: expect.stringContaining('before'),
      });
    }
  });
});

